begin;
alter table public.erp_financeiro_baixas enable row level security;
alter table public.erp_financeiro_parcelas enable row level security;
alter table public.erp_financeiro_titulos enable row level security;
alter table public.erp_grupos enable row level security;
do $$ declare r record; begin
 for r in select tablename,policyname from pg_policies where schemaname='public' and tablename=any(array['erp_financeiro_baixas','erp_financeiro_parcelas','erp_financeiro_titulos','erp_grupos'])
 loop execute format('drop policy if exists %I on public.%I',r.policyname,r.tablename); end loop;
end $$;
create policy erp_financeiro_baixas_tenant_guard on public.erp_financeiro_baixas as restrictive for all to authenticated using (((empresa_id = erp_current_empresa_id()) OR erp_is_master())) with check (((empresa_id = erp_current_empresa_id()) OR erp_is_master()));
create policy erp_financeiro_baixas_delete_rbac on public.erp_financeiro_baixas as permissive for delete to authenticated using ((( SELECT erp_is_master() AS erp_is_master) OR ((empresa_id = ( SELECT erp_current_empresa_id() AS erp_current_empresa_id)) AND ( SELECT (erp_has_permission('finance.update'::text) OR erp_has_permission('finance.approve'::text) OR erp_has_permission('financeiro'::text, 'excluir'::text))))));
create policy erp_financeiro_baixas_insert_rbac on public.erp_financeiro_baixas as permissive for insert to authenticated with check ((( SELECT erp_is_master() AS erp_is_master) OR ((empresa_id = ( SELECT erp_current_empresa_id() AS erp_current_empresa_id)) AND ( SELECT (erp_has_permission('finance.create'::text) OR erp_has_permission('financeiro'::text, 'criar'::text))))));
